"""Build the PathSnap technical report from measured project evidence."""
from pathlib import Path
from reportlab.lib import colors
from reportlab.lib.enums import TA_CENTER
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.units import mm
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, Image, PageBreak

ROOT=Path(__file__).resolve().parents[1]
ASSETS=Path(__file__).resolve().parent/'figures'
OUT=ROOT/'reports'/'PathSnap_Phase2_Technical_Report.pdf'
s=getSampleStyleSheet()
s.add(ParagraphStyle(name='Cover',parent=s['Title'],fontSize=27,leading=32,textColor=colors.HexColor('#13345b'),alignment=TA_CENTER))
s.add(ParagraphStyle(name='Sub',parent=s['Normal'],fontSize=12,leading=18,alignment=TA_CENTER,textColor=colors.HexColor('#536579')))
s.add(ParagraphStyle(name='H1x',parent=s['Heading1'],fontSize=17,leading=21,textColor=colors.HexColor('#13345b'),spaceAfter=8))
s.add(ParagraphStyle(name='H2x',parent=s['Heading2'],fontSize=12,leading=16,textColor=colors.HexColor('#1769aa'),spaceBefore=6,spaceAfter=5))
s.add(ParagraphStyle(name='B',parent=s['BodyText'],fontSize=9.2,leading=13,spaceAfter=7))
s.add(ParagraphStyle(name='Small',parent=s['BodyText'],fontSize=8,leading=10,textColor=colors.HexColor('#526273')))
def p(text,style='B'): return Paragraph(text,s[style])
def figure(file,width=160*mm):
    f=ASSETS/file
    probe=Image(str(f))
    return Image(str(f),width=width,height=width*probe.imageHeight/probe.imageWidth)
def table(rows,widths):
    t=Table(rows,colWidths=widths,repeatRows=1)
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#17385e')),('TEXTCOLOR',(0,0),(-1,0),colors.white),('FONTNAME',(0,0),(-1,0),'Helvetica-Bold'),('GRID',(0,0),(-1,-1),.35,colors.HexColor('#cbd5e1')),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#f3f7fb')]),('FONTSIZE',(0,0),(-1,-1),8),('LEADING',(0,0),(-1,-1),10),('VALIGN',(0,0),(-1,-1),'MIDDLE'),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),6)]))
    return t
def footer(c,d):
    c.saveState();c.setFont('Helvetica',8);c.setFillColor(colors.HexColor('#728096'));c.drawString(18*mm,12*mm,'PathSnap · Phase 2 technical report');c.drawRightString(A4[0]-18*mm,12*mm,str(d.page));c.restoreState()
doc=SimpleDocTemplate(str(OUT),pagesize=A4,rightMargin=18*mm,leftMargin=18*mm,topMargin=17*mm,bottomMargin=20*mm,title='PathSnap Phase 2 Technical Report',author='PathSnap Team')
st=[]
# Page 1
st += [Spacer(1,42*mm),p('PATHSNAP','Cover'),p('Phase 2 · Technical Report & Working Evaluation','Sub'),Spacer(1,12*mm),p('GPS map matching from noisy observations to a connected road route','Sub'),Spacer(1,25*mm),p('Project outcome','H1x'),p('A reproducible notebook pipeline explores and preprocesses the supplied trips, creates road-segment candidates and movement features, compares five classifier families, tunes the selected family with grouped Bayesian optimization, and serves route predictions through a local API and browser interface. The presentation can run across two laptops on one local network.'),Spacer(1,8*mm),p('<b>Selected model:</b> Hist Gradient Boosting &nbsp; <b>Selection:</b> five-fold GroupKFold candidate Macro F1 &nbsp; <b>Tuning:</b> 15 Optuna TPE trials'),Spacer(1,28*mm),p('Prepared from the supplied dataset, project notebooks, and evaluation instructions. Results and limitations are reported as measured.','Sub'),PageBreak()]
# Page 2
st += [p('1. Problem, data and preprocessing','H1x'),p('PathSnap receives a time-ordered GPS track and a trip-specific directed road graph. It associates noisy observations with plausible road segments and reconstructs a spatially coherent route. The files are <font name="Courier">.track</font> (coordinates/timestamps), <font name="Courier">.nodes</font> (graph coordinates), <font name="Courier">.arcs</font> (directed edges), and <font name="Courier">.route</font> (reference path).'),p('The supplied student partition has 80 training trips and 10 student-test trips. The separate evaluator archive contains 10 trips. Training trips are used for grouped CV and tuning; student-test is used for development comparison. Evaluator data is excluded from model fitting/tuning and accessed only by the server-side final evaluation path.'),p('The preprocessing notebook inventories all four files, validates parseability and coordinate ranges, checks timestamp order and time gaps, and verifies arc endpoints against node indices. Coordinates are projected to local metres for distance calculations while longitude/latitude are retained for visualization. Track rows retain temporal order.'),p('For each GPS point, candidate generation ranks arcs by distance to segment midpoint and retains the nearest 12. The same five Phase 1 features are retained: perpendicular GPS-to-segment distance; absolute difference between GPS movement heading and road heading; clipped projection position along the segment (0 to 1); segment length; and GPS speed since the prior observation. Arc IDs are trip-local and are not used as global classes.'),p('Labels are approximated by the nearest segment among the supplied reference route. Crossings and loops can make these labels ambiguous. If the correct arc is absent from the 12-candidate shortlist, the classifier cannot recover it; candidate miss rate is measured separately.'),figure('phase2_student_map.png',150*mm),p('Figure 1. Student-development route overview in local projected coordinates. GPS observations, reference path, and predicted route are displayed for one example; the curves largely overlap.','Small'),PageBreak()]
# Page 3
st += [p('2. Five-model comparison','H1x'),p('Model selection used five-fold GroupKFold over training trips so rows from a trip cannot appear in both fit and validation folds. Candidate-level Macro F1 was the predeclared selection objective. Observation Top-1 selects the highest-scoring candidate at each GPS point and is a different metric.'),table([['Model','CV Macro F1\nmean ± SD','CV Top-1','Student Top-1','Student Macro F1'],['Logistic Regression','0.6358 ± 0.0382','50.23%','57.80%','0.6088'],['KNN','0.7202 ± 0.0188','59.53%','66.11%','0.7233'],['Decision Tree','0.7981 ± 0.0143','65.76%','73.32%','0.7980'],['Random Forest','0.8327 ± 0.0183','68.47%','75.23%','0.8413'],['Hist Gradient Boosting','0.8485 ± 0.0251','67.87%','75.44%','0.8613']],[40*mm,37*mm,28*mm,29*mm,38*mm]),Spacer(1,7*mm),figure('phase2_cv_macro_f1.png',165*mm),Spacer(1,5*mm),p('Hist Gradient Boosting had the highest mean CV candidate Macro F1. Random Forest had slightly higher mean CV observation Top-1, so the choice is supported by the stated Macro F1 objective, not a claim that HGB wins every metric.'),PageBreak()]
# Page 4
st += [p('3. Bayesian optimization and final model','H1x'),p('Optuna TPE searched 15 Hist Gradient Boosting configurations. Every trial used the same five grouped training folds; the objective was mean candidate Macro F1. Best parameters: <font name="Courier">max_iter=60</font>, <font name="Courier">learning_rate=0.0259</font>, <font name="Courier">max_leaf_nodes=31</font>, <font name="Courier">min_samples_leaf=47</font>, and <font name="Courier">l2_regularization=0.0487</font>.'),Spacer(1,3*mm),figure('phase2_tuning_f1.png',155*mm),Spacer(1,4*mm),p('Tuning raised CV Macro F1 modestly from 0.8485 to 0.8516 (fold SD 0.0279 vs 0.0251). On student-test, candidate Macro F1 rose from 0.8613 to 0.8667; Top-1 moved from 75.44% to 75.40%; recall fell from 0.8720 to 0.8348; log loss worsened from 0.1067 to 0.1352. The tuned bundle is retained because the declared optimization target improved; the tradeoffs are disclosed.'),p('The saved bundle is <font name="Courier">outputs/phase2_model.joblib</font>. The notebook also saves CV folds, trial history, student comparisons, and tuned/untuned metrics as CSV/JSON evidence.'),PageBreak()]
# Page 5
st += [p('4. Viterbi route reconstruction and final check','H1x'),p('Each candidate arc is a hidden state. Emission scores are classifier probabilities. Transition scores favor directed connectivity, mildly penalize staying on the same arc, and penalize disconnected arcs; the disconnection penalty is relaxed for GPS gaps above five seconds. Dynamic programming tracks cumulative scores and backpointers to reconstruct the route.'),p('Across 10 student-test trips (19,160 observations), classifier Top-1 was 75.40% and Viterbi Top-1 was 56.10%; trip-mean direct-arc continuity improved from 25.69% to 77.80%. The simple decoder improves connectivity at a substantial point-accuracy cost because it does not search multi-arc shortest paths between samples.'),p('After freezing the model and decoder, the API processed all 10 evaluator trips (19,674 observations). Metrics were computed server-side after prediction and were not used to revise features, model, hyperparameters, or decoder.'),table([['Final evaluator metric','Classifier','After Viterbi'],['Observation-level Top-1','69.49%','54.36%'],['Trip-mean direct-arc continuity','30.12%','81.40%'],['Candidate miss rate','4.79%','—']],[77*mm,42*mm,42*mm]),Spacer(1,4*mm),figure('evaluator_metrics.png',155*mm),p('These metrics use nearest-reference-segment label approximation and should not be described as exact route-level accuracy.','Small'),PageBreak()]
# Page 6
st += [p('5. Two-laptop presentation and deliverables','H1x'),p('<b>Laptop 1:</b> keep the model and evaluator ZIP locally; start Uvicorn bound to <font name="Courier">0.0.0.0:8000</font> and allow private-network access if prompted. <b>Laptop 2:</b> serve <font name="Courier">web/</font> at <font name="Courier">127.0.0.1:8080</font>, open the browser page, enter Laptop 1’s LAN IP and port 8000, then connect. Both devices must share a trusted LAN. Inference, route-label access, and metric calculation stay on Laptop 1; Laptop 2 receives predictions and metrics. Exact commands are in README.'),p('Repository deliverables: source code and six executed notebooks; data preprocessing and feature engineering; five-model comparison and tuned model artifact; CV, trial, student and route-decoder evidence; FastAPI + Folium interface; installation/two-laptop README; this technical report. Raw training/student/evaluator archives and per-trip evaluator outputs are excluded from Git.'),p('Limitations and presentation note','H2x'),p('The decoder improves direct connectivity but reduces pointwise accuracy. Candidate coverage is not perfect. Labels are approximate, only 15 tuning trials were run, and the five-fold CV uses one grouping design. A stronger decoder should consider shortest paths through intermediate arcs. Team members should review and understand the notebooks and follow course rules for disclosing assistance.')]
doc.build(st,onFirstPage=footer,onLaterPages=footer)
print(OUT)
